void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    // Normalize pixel coordinates
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;

    // Circle properties
    float radius = 0.1;
    vec3 circleColor = vec3(0.3, 0.6, 1.0);

    // Get stored position from Buffer A
    vec2 circlePos = texture(iChannel0, vec2(0.0)).xy;

    // Draw the circle
    float circle = length(uv - circlePos) - radius;
    float smoothCircle = smoothstep(0.0, 0.005, circle);

    // Add a subtle glow when being dragged
    float glow = 0.0;
    if (iMouse.z > 0.0) {
        glow = exp(-circle * 8.0) * 0.5;
    }

    // Output final color with glow
    vec3 color = mix(circleColor + vec3(glow), vec3(0.1), smoothCircle);
    fragColor = vec4(color, 1.0);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord/iResolution.xy;
    vec2 mouse = (iMouse.xy - 0.5 * iResolution.xy) / iResolution.y;

    // Only update if we're at pixel (0,0) to store single position
    if (fragCoord.x < 1.0 && fragCoord.y < 1.0) {
        if (iFrame == 0) {
            // Initialize to center
            fragColor = vec4(0.0, 0.0, 0.0, 1.0);
        } else {
            // Load previous position
            vec4 prevPos = texture(iChannel0, uv);

            // Update position if dragging, otherwise keep previous
            fragColor = (iMouse.z > 0.0) ? vec4(mouse, 0.0, 1.0) : prevPos;
        }
    } else {
        // Keep previous value for all other pixels
        fragColor = texture(iChannel0, uv);
    }
}
